3	export function DisplayTruncatedPath({ path }: { path: string }) {
4	  const isWindows = path.includes('\\');
5	  const parts = isWindows ? path.split('\\') : path.split('/');
6	
7	  return (
8	    <div className="h-[1lh] overflow-hidden">
9	      <div className="flex flex-row-reverse flex-wrap justify-end relative pl-2">
10	        <EllipsisComponent className="bottom-[1lh]" />
11	        <EllipsisComponent className="bottom-[2lh]" />
12	        <EllipsisComponent className="bottom-[3lh]" />
13	        <EllipsisComponent className="bottom-[4lh]" />
14	        <EllipsisComponent className="bottom-[5lh]" />
15	        <EllipsisComponent className="bottom-[6lh]" />
16	        <EllipsisComponent className="bottom-[7lh]" />
17	        <EllipsisComponent className="bottom-[8lh]" />
18	        <EllipsisComponent className="bottom-[9lh]" />
19	        <EllipsisComponent className="bottom-[10lh]" />
20	
21	        {parts.reverse().map((part, index) => (
22	          <span className="flex-none font-ibm-plex-mono " key={index}>
23	            {isWindows ? '\\' : '/'}
24	            {part}
25	          </span>
26	        ))}
27	      </div>
28	    </div>
29	  );
30	}
31	
32	const EllipsisComponent = ({ className }: { className: string }) => {
33	  return (
34	    <div
35	      className={cn('absolute -translate-x-full tracking-tighter', className)}
36	    >
37	      ...
38	    </div>
39	  );
40	};
