121	const makeRequest = async (url: string, options: RequestInit = {}) => {
122	  const headers = new Headers(options.headers ?? {});
123	  if (!headers.has('Content-Type')) {
124	    headers.set('Content-Type', 'application/json');
125	  }
126	
127	  return makeLocalApiRequest(url, {
128	    ...options,
129	    headers,
130	  });
131	};
